-- PostgreSQL schema for the independent interests/lifestyle component.
-- Requires an existing users(id TEXT PRIMARY KEY) table.
-- The full local Shiny app still uses SQLite; this is the component's porting schema.
BEGIN;
CREATE TABLE IF NOT EXISTS interest_categories(id TEXT PRIMARY KEY,label TEXT NOT NULL,sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS interests(id TEXT PRIMARY KEY,category_id TEXT NOT NULL REFERENCES interest_categories(id),label TEXT NOT NULL,sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lifestyle_questions(id TEXT PRIMARY KEY,prompt TEXT NOT NULL,measurement_type TEXT NOT NULL,options TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS questionnaire_versions(id TEXT PRIMARY KEY,instrument_id TEXT NOT NULL,version TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(instrument_id,version));
CREATE TABLE IF NOT EXISTS questionnaire_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),status TEXT NOT NULL CHECK(status IN ('draft','completed')),step INTEGER NOT NULL CHECK(step BETWEEN 1 AND 6),navigation TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS questionnaire_sessions_owner ON questionnaire_sessions(user_id,questionnaire_version_id,updated_at);
CREATE TABLE IF NOT EXISTS user_interests(session_id TEXT NOT NULL REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),interest_id TEXT NOT NULL REFERENCES interests(id),enjoyment INTEGER CHECK(enjoyment BETWEEN 1 AND 5),frequency INTEGER CHECK(frequency BETWEEN 1 AND 5),updated_at TEXT NOT NULL,PRIMARY KEY(session_id,interest_id));
CREATE TABLE IF NOT EXISTS user_interest_partner_preferences(session_id TEXT NOT NULL REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),interest_id TEXT NOT NULL REFERENCES interests(id),importance INTEGER CHECK(importance BETWEEN 1 AND 5),updated_at TEXT NOT NULL,PRIMARY KEY(session_id,interest_id));
CREATE TABLE IF NOT EXISTS lifestyle_responses(session_id TEXT NOT NULL REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),question_id TEXT NOT NULL REFERENCES lifestyle_questions(id),option_value TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(session_id,question_id));
CREATE TABLE IF NOT EXISTS lifestyle_partner_preferences(session_id TEXT NOT NULL REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),question_id TEXT NOT NULL REFERENCES lifestyle_questions(id),importance INTEGER CHECK(importance BETWEEN 1 AND 5),updated_at TEXT NOT NULL,PRIMARY KEY(session_id,question_id));
CREATE TABLE IF NOT EXISTS shared_activity_preferences(session_id TEXT NOT NULL REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,questionnaire_version_id TEXT NOT NULL REFERENCES questionnaire_versions(id),activity_id TEXT NOT NULL,importance INTEGER CHECK(importance BETWEEN 1 AND 3),updated_at TEXT NOT NULL,PRIMARY KEY(session_id,activity_id));
CREATE TABLE IF NOT EXISTS custom_interest_suggestions(session_id TEXT PRIMARY KEY REFERENCES questionnaire_sessions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,suggestion TEXT NOT NULL,updated_at TEXT NOT NULL);
COMMIT;
